if($vista==='curso'&&$cursoBoletin){
    $estudiantesBoletin=ControladorCalificaciones::crtEstudiantesPorCurso($idCursoBoletin);
    foreach($cierres as $cierreBoletin){
        if((int)($cierreBoletin['idCurso']??0)!==$idCursoBoletin||($cierreBoletin['calificacionCierre']??null)===null){continue;}
